Lemma addressable_transport_scr : forall LF m0 X XS m m' O n,
  as_RFS H LF m0 -> fsobj H LF O n -> aapp O n ->
  addressable m O n -> munch (X ++ XS) m m' -> wmono bsegs m m' -> Forall awin X -> Forall (fs_scratch H LF) XS -> addressable m' O n.
Proof.
  intros LF m0 X XS m m' O n RF FO AP AD MU WM FX FS. pose proof AD as (Hn & _).
  pose proof (aapp_bounds _ _ AP Hn) as (B1 & B2 & B3 & B4 & B5).
  eapply addressable_transport; [exact AD| exact MU| exact WM|]. apply disjoint_from_app2.
  - apply awin_disjoint_shland; [exact FX| apply sh_ge_lowsh; lia| apply sh_nsh_high; lia].
  - eapply (disjoint_scratch_sh H HH); [exact RF| exact FO| exact Hn| lia| exact AP| exact FS].
Qed.

Lemma RHEAP_transport_scr : forall s LB LF m0 X XS m m',
  as_RHEAP H s LB m -> as_RFS H LF m0 -> munch (X ++ XS) m m' -> wmono bsegs m m' ->
  Forall (aclient_write_ok H LB) X -> Forall (fs_scratch H LF) XS -> as_RHEAP H s LB m'.
Proof.
  intros s LB LF m0 X XS m m' RH RF MU WM FX FS.
  eapply (ah_RHEAP_frame H HH); [exact RH| exact MU| exact WM|]. apply Forall_app. split; [exact FX|].
  exact (proj1 (scratch_Forall H HH LF m0 LB XS RF FS)).
Qed.


(* [comment removed for export] *)
Lemma sub_fp_scr : forall lo sp v hv (XS : list (Z * Z)) l h d dh (XS1 : list (Z * Z)),
  lo <= l -> h <= sp -> v <= d -> dh <= hv -> (forall x, outside XS x -> outside XS1 x) ->
  sub_fp ((l, h) :: (d, dh) :: XS1)%Z ((lo, sp) :: (v, hv) :: XS)%Z.
Proof.
  intros lo sp v hv XS l h d dh XS1 H1 H2 H3 H4 HS x O. cbn in O |- *. destruct O as (O1 & O2 & O3).
  split; [lia| split; [lia| apply HS; exact O3]].
Qed.
Lemma sub_fp_two : forall lo sp v hv (XS : list (Z * Z)), sub_fp [(lo, sp); (v, hv)]%Z ((lo, sp) :: (v, hv) :: XS)%Z.
Proof. intros lo sp v hv XS x O. cbn in O |- *. tauto. Qed.

(* [comment removed for export] *)
Lemma rw_cells_transport_scr : forall LF m0 X XS m m' A cs,
  as_RFS H LF m0 -> fsobj H LF A (Z.of_nat (cells_size cs)) -> aapp A (Z.of_nat (cells_size cs)) ->
  rw_cells bsegs m A cs -> munch (X ++ XS) m m' -> wmono bsegs m m' -> disjoint_from X A (Z.of_nat (cells_size cs)) ->
  Forall (fs_scratch H LF) XS -> rw_cells bsegs m' A cs.
Proof.
  intros LF m0 X XS m m' A cs RF FO AP RC MU WM DX FS.
  pose proof (aapp_bounds _ _ AP ltac:(lia)) as (B1 & B2 & B3 & B4 & B5).
  eapply rw_cells_transport; [exact RC| exact MU| exact WM|]. apply disjoint_from_app2; [exact DX|].
  eapply (disjoint_scratch H HH); [exact RF| exact FO| lia| lia| exact AP| exact FS].
Qed.

Lemma rw_cells_transport_scr_hi : forall LF m0 X XS m m' A cs,
  as_RFS H LF m0 -> aceil <= A ->
  rw_cells bsegs m A cs -> munch (X ++ XS) m m' -> wmono bsegs m m' -> disjoint_from X A (Z.of_nat (cells_size cs)) ->
  Forall (fs_scratch H LF) XS -> rw_cells bsegs m' A cs.
Proof.
  intros LF m0 X XS m m' A cs RF HA RC MU WM DX FS.
  eapply rw_cells_transport; [exact RC| exact MU| exact WM|]. apply disjoint_from_app2; [exact DX|].
  exact (proj2 (proj2 (scratch_Forall H HH LF m0 [] XS RF FS)) A _ HA).
Qed.

Lemma stk_transport_scr : forall LF m0 X XS m m' l h,
  as_RFS H LF m0 -> aceil <= l ->
  stk bsegs m l h -> munch (X ++ XS) m m' -> wmono bsegs m m' -> disjoint_from X l (h - l) ->
  Forall (fs_scratch H LF) XS -> stk bsegs m' l h.
Proof.
  intros LF m0 X XS m m' l h RF HA ST MU WM DX FS.
  eapply stk_transport_disjoint; [exact ST| exact MU| exact WM|]. apply disjoint_from_app2; [exact DX|].
  exact (proj2 (proj2 (scratch_Forall H HH LF m0 [] XS RF FS)) l _ HA).
Qed.

Lemma bytes_at_transport_scr : forall LF m0 X XS m m' A bs,
  as_RFS H LF m0 -> (bs <> [] -> fsobj H LF A (Z.of_nat (length bs)) /\ aapp A (Z.of_nat (length bs))) ->
  bytes_at bsegs m A bs -> munch (X ++ XS) m m' -> disjoint_from X A (Z.of_nat (length bs)) ->
  Forall (fs_scratch H LF) XS -> bytes_at bsegs m' A bs.
Proof.
  intros LF m0 X XS m m' A bs RF OB BA MU DX FS.
  destruct bs as [|b0 bs']; [eapply bytes_at_nil; exact BA|].
  destruct (OB ltac:(congruence)) as [FO AP].
  pose proof (aapp_bounds _ _ AP ltac:(lia)) as (B1 & B2 & B3 & B4 & B5).
  eapply bytes_at_transport; [exact BA| exact MU|]. apply disjoint_from_app2; [exact DX|].
  eapply (disjoint_scratch H HH); [exact RF| exact FO| lia| lia| exact AP| exact FS].
Qed.

(* [comment removed for export] *)
Definition scrW (ff fp : Z) : list (Z * Z) := [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 64); (sh ff, sh ff + 8)]%Z.

Lemma scrW_scratch : forall LF ff fp, fresh_frame H LF 0 ff fp -> Forall (fs_scratch H LF) (scrW ff fp).
Proof. intros LF ff fp FF. exact (fs_scratch_of_fresh H LF 0 ff fp FF). Qed.

Lemma svc_W_split : forall lo sp dst n ff fp, svc_W H lo sp dst n ff fp = [(lo, bv_unsigned sp); (dst, dst + n)]%Z ++ scrW ff fp.
Proof. reflexivity. Qed.

(* [comment removed for export] *)
Definition win_obj (LB : list block) (LF : list fframe) (m : mem) (bs : list byte) (A : Z) : Prop :=
  bs <> [] -> aobj LB LF A (zlength bs) /\ accessible m A (zlength bs).

Lemma win_obj_awin : forall LB LF W m m' bs A, win_obj LB LF m bs A -> munch W m m' -> Forall awin W -> win_obj LB LF m' bs A.
Proof. intros LB LF W m m' bs A WO MU FW NE. destruct (WO NE) as [AO AC]. split; [exact AO| eapply accessible_transport_awin; eauto]. Qed.

Lemma win_obj_scr : forall s LB LF m0 m1 X XS m m' bs A,
  as_RHEAP H s LB m0 -> as_RFS H LF m1 -> win_obj LB LF m bs A -> munch (X ++ XS) m m' -> Forall awin X -> Forall (fs_scratch H LF) XS ->
  win_obj LB LF m' bs A.
Proof.
  intros s LB LF m0 m1 X XS m m' bs A RH RF WO MU FX FS NE. destruct (WO NE) as [AO AC]. split; [exact AO|].
  eapply (accessible_transport_scr LF m1 X XS m m'); [exact RF| eapply (aobj_fsobj H HH); [exact RH| exact AO]
    | eapply (aobj_aapp H HH); [exact RH| exact RF| exact AO] | unfold zlength; lia| exact AC| exact MU| exact FX| exact FS].
Qed.


Lemma win_obj_fs : forall s LB LF m0 m1 m bs A, as_RHEAP H s LB m0 -> as_RFS H LF m1 -> win_obj LB LF m bs A ->
  bs <> [] -> fsobj H LF A (Z.of_nat (length bs)) /\ aapp A (Z.of_nat (length bs)).
Proof.
  intros s LB LF m0 m1 m bs A RH RF WO NE. destruct (WO NE) as [AO _]. unfold zlength in AO.
  split; [eapply (aobj_fsobj H HH); [exact RH| exact AO]| eapply (aobj_aapp H HH); [exact RH| exact RF| exact AO]].
Qed.

(* [comment removed for export] *)
Lemma win_svc_obj : forall s LB LF m bs A, as_RHEAP H s LB m -> as_RFS H LF m -> win_obj LB LF m bs A -> svc_obj H LF m bs A.
Proof.
  intros s LB LF m bs A RH RF WO NE. destruct (WO NE) as [AO AC]. unfold X8_svcopy.zlength. unfold zlength in *.
  split; [eapply (aobj_aapp H HH); [exact RH| exact RF| exact AO]|]. split; [exact AC|].
  split; [eapply (aobj_shvis H HH); [exact RH| exact RF| exact AO| lia]| eapply (aobj_fsobj H HH); [exact RH| exact AO]].
Qed.

