(* [comment removed for export] *)
Definition VT_STACK : Z := 80 + SVC_STACK.

Definition vtc_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (s : as_St H) (LB : list block) (LF : list fframe)
    (v f np vp : Z) (name value : list byte) (tl lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' pad tail XS,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch ((lo, bv_unsigned sp) :: (v, v + 12 + zlength name + zlength value + tl) :: XS)%Z m m'
    /\ Forall (fs_scratch H LF) XS
    /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' v (ValCells (mkElt f name value pad tail)) /\ zlength tail = tl
    /\ bytes_at bsegs m' np name /\ bytes_at bsegs m' vp value
    /\ as_RHEAP H s LB m' /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.

Definition vtc_stmt : Prop := forall (s : as_St H) (LB : list block) (LF : list fframe)
    (v f np vp : Z) (name value : list byte) (tl lo shi : Z) (n : nat) (junk : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells bsegs m v [CB n junk] -> Z.of_nat n = 12 + zlength name + zlength value + tl -> 0 <= tl ->
  bytes_at bsegs m np name -> bytes_at bsegs m vp value ->
  zlength name + 2 < 2^16 -> zlength value < 2^16 -> 0 <= f < 2^16 ->
  (np + zlength name <= v \/ v + Z.of_nat n <= np) -> (vp + zlength value <= v \/ v + Z.of_nat n <= vp) ->
  (np + zlength name <= lo \/ bv_unsigned sp <= np) -> (vp + zlength value <= lo \/ bv_unsigned sp <= vp) ->
  stk bsegs m lo (bv_unsigned sp) -> lo + VT_STACK <= bv_unsigned sp -> aceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> tp = Z_to_bv 64 ATP -> ACONST m ->
  as_RHEAP H s LB m -> as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp <= shi ->
  aobj LB LF v (Z.of_nat n) -> v mod 8 = 0 -> Z.of_nat n mod 8 = 0 -> accessible m v (Z.of_nat n) ->
  win_obj LB LF m name np -> win_obj LB LF m value vp ->
  evt bsegs (vtc_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF v f np vp name value tl lo shi m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 v) (Z_to_bv 64 f) (Z_to_bv 64 np) (Z_to_bv 64 (zlength name))
              (Z_to_bv 64 vp) (Z_to_bv 64 (zlength value)) a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_FIELDS_VALUE_TYPE_CTOR) fc None m (seg_rom bsegs)).

(* [comment removed for export] *)
Tactic Notation "scr_keep_hi" hyp(Hc) "over" hyp(MU) hyp(WM) hyp(RF) hyp(FS) "by" tactic3(tac) :=
  lazymatch type of MU with munch (?X ++ ?XS) ?m ?m' =>
  lazymatch type of Hc with
  | rw_cells _ _ ?A ?cs =>
      let N := fresh "KEEP" in
      assert (N : rw_cells bsegs m' A cs)
        by (eapply (rw_cells_transport_scr_hi _ _ X XS m m' A cs RF);
            [ tac | exact Hc | exact MU | exact WM | fit_zsizes; cbn [disjoint_from fst snd cells_size csize Nat.add]; tac | exact FS ]);
      clear Hc; rename N into Hc
  | stk _ _ ?l ?h =>
      let N := fresh "KEEP" in
      assert (N : stk bsegs m' l h)
        by (eapply (stk_transport_scr _ _ X XS m m' l h RF);
            [ tac | exact Hc | exact MU | exact WM | cbn [disjoint_from fst snd]; tac | exact FS ]);
      clear Hc; rename N into Hc
  end end.
Tactic Notation "scr_keep" hyp(Hc) "as" constr(OB) "over" hyp(MU) hyp(WM) hyp(RF) hyp(FS) "by" tactic3(tac) :=
  lazymatch type of MU with munch (?X ++ ?XS) ?m ?m' =>
  lazymatch type of Hc with
  | rw_cells _ _ ?A ?cs =>
      let N := fresh "KEEP" in
      assert (N : rw_cells bsegs m' A cs)
        by (eapply (rw_cells_transport_scr _ _ X XS m m' A cs RF);
            [ exact (proj1 OB) | exact (proj2 OB) | exact Hc | exact MU | exact WM
            | fit_zsizes; cbn [disjoint_from fst snd cells_size csize Nat.add]; tac | exact FS ]);
      clear Hc; rename N into Hc
  end end.

(* [comment removed for export] *)
Local Ltac vchk ACV MU FW VAL NAL a :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let RD := fresh "RD" in
    pose proof (acc8_rd0 mc _ _ a (accessible_transport_awin _ _ _ _ _ ACV MU FW) VAL NAL ltac:(lia)) as RD
  end.
Scheme kc__3 := Elimination for Corelib.Init.Logic.ex Sort Prop.
Scheme kc__4 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

