(* [comment removed for export] *)

Definition P_A_TCNE_RET1 : Z := 0xbce88.     (* [comment removed for export] *)
Definition P_B_ALLOCATE_A8 : Z := 0xbd360.   (* [comment removed for export] *)

(* [comment removed for export] *)
Lemma drop_ws_wspan : forall bs, drop_ws bs = skipn (wspan (zbytes bs)) bs.
Proof.
  induction bs as [|b bs IH]; [reflexivity|]. cbn [drop_ws zbytes map wspan].
  unfold is_ws at 1. unfold AXPRep.is_ws. destruct ((zb b =? 32) || (zb b =? 9)); [| reflexivity].
  cbn [skipn]. exact IH.
Qed.

Lemma wspan_stop : forall s, (wspan s < length s)%nat -> AXPRep.is_ws (nth (wspan s) s 0) = false.
Proof.
  induction s as [|c s IH]; intros Hk; cbn in Hk |- *; [lia|].
  destruct (AXPRep.is_ws c) eqn:W; [| cbn; exact W]. cbn. apply IH. lia.
Qed.

(* [comment removed for export] *)
Lemma shl3_shr3 : forall x, 0 <= x -> Z.shiftl (Z.shiftr x 3) 3 = x - x mod 8.
Proof.
  intros x Hx. rewrite Z.shiftr_div_pow2, Z.shiftl_mul_pow2 by lia. change (2 ^ 3) with 8.
  pose proof (Z.div_mod x 8 ltac:(lia)). lia.
Qed.

Lemma shr3_shr61 : forall x, 0 <= x < 2^64 -> Z.shiftr (Z.shiftr x 3) 61 = 0.
Proof. intros x Hx. rewrite Z.shiftr_shiftr by lia. change (3 + 61) with 64. rewrite Z.shiftr_div_pow2 by lia. apply Z.div_small. lia. Qed.

Lemma ebs_eq : forall name tv,
  elem_block_size name tv = (zlength name + zlength tv + 67) - (zlength name + zlength tv + 67) mod 8.
Proof.
  intros name tv. unfold elem_block_size, zlength. rewrite land_neg8 by lia.
