(* [comment removed for export] *)
Definition tc_frame (m : mem) (sp ra s0 s1 s2 s3 s4 s5 s6 s7 : word) (junk : list byte) : Prop :=
  rw_cells bsegs m (bv_unsigned sp + -96) [CB 24 junk; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

Definition TC_SEG_STACK : Z := 96 + SKIP_OWS_STACK.

(* [comment removed for export] *)
Definition tc_seg1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (f np vp : Z) (name value : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' junk s3x p5 msk vp',
    ms' = MS (mkR (Z_to_bv 64 P_A_TCNE_RET1) (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2
                  (Z_to_bv 64 (zlength name)) (Z_to_bv 64 np) (Z_to_bv 64 (elem_block_size name (trim value))) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 f) s3x (Z_to_bv 64 (zlength (trim value))) (Z_to_bv 64 msk) (Z_to_bv 64 2147450880) (Z_to_bv 64 p5)
                  s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 AOPNEW) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -96)
    /\ tc_frame m' sp ra s0 s1 s2 s3 s4 s5 s6 s7 junk
    /\ Z.land msk p5 = vp' /\ 0 <= p5 < 2^64 /\ 0 <= msk < 2^64
    /\ bytes_at bsegs m' vp' (trim value)
    /\ ((vp <= vp' /\ vp' + zlength (trim value) <= vp + zlength value) \/ (vp' = 0 /\ trim value = [])).

Definition tc_seg1_stmt : Prop := forall (Fa f np vp ec : Z) (name value : list byte) (lo shi : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  bytes_at bsegs m vp value ->
  zlength name <= 65533 -> zlength value <= 65533 -> vp + zlength value < 2^64 ->
  (vp + zlength value <= lo \/ bv_unsigned sp <= vp) ->
  stk bsegs m lo (bv_unsigned sp) -> lo + TC_SEG_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  ACONST m -> (value <> [] -> accessible m vp (zlength value)) ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  (* [comment removed for export] *)
  (0 < zlength value -> 0 < vp) ->
  evt bsegs (tc_seg1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc f np vp name value lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 Fa) (Z_to_bv 64 f) (Z_to_bv 64 np) (Z_to_bv 64 (zlength name))
              (Z_to_bv 64 vp) (Z_to_bv 64 (zlength value)) (Z_to_bv 64 ec) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_FIELDS_NEW_ELEMENT) fc None m (seg_rom bsegs)).

(* [comment removed for export] *)
Local Ltac tc_seg1_close FR MU WM :=
  let ms' := fresh "ms'" in let PO := fresh "PO" in
  intros ms' PO; unfold tc_scan_post in PO;
  let MUx := fresh "MUx" in let WMx := fresh "WMx" in let MIx := fresh "MIx" in let STx := fresh "STx" in
  let E1 := fresh "E1" in let R1 := fresh "R1" in let R2 := fresh "R2" in let TB := fresh "TB" in let CT := fresh "CT" in
  destruct PO as (? & ? & ? & ? & ? & ? & ? & ? & ? & ? & s3x & p5 & msk & vp' & mx
                  & -> & MUx & WMx & MIx & STx & E1 & R1 & R2 & TB & CT);
  rewrite unsigned_lit in MUx, STx by lia;
  lazymatch type of MUx with munch ?W ?ma ?mb => lazymatch type of FR with rw_cells _ _ ?A ?cs =>
    apply (rw_cells_transport bsegs W ma mb A cs) in FR; [| exact MUx | exact WMx | cbn [disjoint_from cells_size csize Nat.add]; lia] end end;
  lazymatch type of MU with munch ?W0 _ _ => lazymatch type of MUx with munch _ ?ma ?mb =>
    let MUw := fresh "MUw" in
    assert (MUw : munch W0 ma mb) by (eapply munch_weaken; [| exact MUx]; unfold sub_fp; cbn [outside]; intros; lia);
    pose proof (munch_trans _ _ _ _ MU MUw) end end;
  pose proof (wmono_trans bsegs _ _ _ WM WMx);
  apply evt_done; unfold tc_seg1_post, tc_frame;
  do 14 eexists; exists mx; eexists; exists s3x, p5, msk, vp';
  split; [reflexivity|]; split; [eassumption|]; split; [eassumption|]; split; [exact MIx|]; split; [exact STx|];
  split;
  [ lazymatch type of FR with rw_cells _ ?my ?base ?cs =>
      apply (rw_cells_merge bsegs my base [] (firstn 2 cs) (skipn 2 cs)); cbn [firstn skipn app]; exact FR end
  | split; [exact E1|]; split; [exact R1|]; split; [exact R2|]; split; [exact TB| exact CT] ].

Lemma tc_seg1 : tc_seg1_stmt.
